window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[109]={"id":"109","numero":109,"titre":"Item 109 — Troubles de la marche et de l'équilibre","objectifs":[{"id":"109-1","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les éléments de l’interrogatoire devant un trouble de la marche","contenu":"<p>L'interrogatoire est un <span class=\"kw-clinique\">temps essentiel</span> de toute démarche clinique devant un trouble de la marche : il oriente d'emblée vers une étiologie et chiffre le retentissement.</p>\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Points à faire préciser</h4>\n      <ul>\n        <li><strong>Date de début</strong> et <strong>mode d'installation</strong> des troubles (brutal, progressif, par poussées).</li>\n        <li><strong>Type de la plainte principale :</strong> <span class=\"kw-clinique\">douleur</span> et sa <strong>relation avec l'effort</strong>, faiblesse, <span class=\"kw-clinique\">instabilité</span> (à bien différencier d'un <span class=\"kw-clinique\">vertige</span>), petits pas, raideur. Le regard d'un tiers est parfois nécessaire — certains signes (ralentissement, perte du ballant d'un bras) sont mieux perçus par l'entourage que par le patient.</li>\n        <li><strong>Sévérité dans la vie quotidienne :</strong> <span class=\"kw-clinique\">chutes</span> ou « presque-chutes » ; conséquences en <strong><span class=\"kw-def\">morbidité</span></strong> (traumatismes, fractures, hospitalisations) ; conséquences sur l'<strong>autonomie</strong> (sorties non accompagnées avec/sans transports en commun, sorties accompagnées, absence de sortie du domicile).</li>\n        <li><strong>Capacité à monter / descendre un escalier :</strong> monter teste la <strong>force</strong>, descendre teste l'<strong>équilibre</strong>. Autonomie pour le ménage, la cuisine, l'habillage, la toilette ; usage d'une <span class=\"kw-ttt\">canne</span>, d'un <span class=\"kw-ttt\">fauteuil roulant</span> ou d'un <span class=\"kw-ttt\">déambulateur</span>.</li>\n        <li><strong>Liste complète des médicaments pris</strong> — <span class=\"kw-alerte\">premier facteur de risque de chute du sujet âgé</span>.</li>\n      </ul>\n      <div class=\"callout callout-warn\">⚠️ Quasiment tous les médicaments prescrits dans le champ <strong>neuropsychiatrique</strong> peuvent induire une baisse de la tension artérielle et des troubles attentionnels → ils majorent le <span class=\"kw-alerte\">risque de chute</span>.</div>","frequence":0},{"id":"109-2","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les modalités de l’examen d’un patient présentant un trouble de la marche","contenu":"<p>L'examen d'un patient présentant un trouble de la marche est <span class=\"kw-clinique\">systématisé</span> : équilibre statique, réflexes posturaux, posture, cinématique articulaire, puis échelles quantifiées.</p>\n      <table >\n        <thead><tr><th>Temps de l'examen</th><th>Modalités et interprétation</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-clinique\">Romberg</span></td>\n            <td><strong>Réalisation :</strong> debout, talons joints, pieds légèrement écartés (~45°), bras ballants ou tendus ; yeux ouverts puis fermés.<br><strong>Instabilité :</strong> signe une <span class=\"kw-def\">ataxie</span> cérébelleuse, vestibulaire ou proprioceptive.<br><strong>Aggravation à la fermeture des yeux :</strong> origine sensorielle (proprioceptive ou vestibulaire) — la contribution visuelle y est majeure.<br><strong>Norme :</strong> un sujet normal tient &gt; <span class=\"kw-chiffre\">6 secondes</span> les yeux fermés.</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-clinique\">Réflexes posturaux</span></td>\n            <td><strong>Manœuvre :</strong> l'examinateur, placé derrière le patient, exerce une <strong>rétropulsion brusque</strong> qui teste les <strong>réflexes d'anticipation</strong>.<br><strong>Altération :</strong> <span class=\"kw-clinique\">lésion</span> des <span class=\"kw-def\">noyaux gris centraux</span> ou des <span class=\"kw-def\">régions frontales</span>.</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-clinique\">Posture — orientation</span></td>\n            <td><strong>Plan sagittal :</strong> flexion du tronc = <span class=\"kw-def\">camptocormie</span> ; atteinte de la nuque = <span class=\"kw-def\">antécolis</span> / <span class=\"kw-def\">rétrocolis</span>.<br><strong>Plan frontal :</strong> inclinaison latérale marquée du tronc = <span class=\"kw-def\">Pisa syndrome</span>.<br><strong>À évaluer :</strong> origine dystonique <span class=\"kw-bio\">vs</span> déficitaire (parfois indécidable).</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-clinique\">Anomalies cinématiques articulaires</span></td>\n            <td><strong>Cheville / pied :</strong> contact initial par l'avant du pied (équin, spasticité du triceps sural, déficit des releveurs).<br><strong>Genou :</strong> recurvatum en phase d'appui, défaut de flexion en phase oscillante (fauchage).<br><strong>Hanche :</strong> circumduction du membre inférieur, défaut d'extension en fin d'appui.<br><strong>Tronc :</strong> manque de dissociation des ceintures (Parkinson), salutation, inclinaison latérale par faiblesse du moyen fessier.<br><strong>Membres supérieurs :</strong> perte du ballant des bras uni- ou bilatérale.</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-clinique\">Échelles</span></td>\n            <td>Quantification standardisée de l'équilibre et de la marche — voir l'objectif dédié « échelles d'analyse ».</td>\n          </tr>\n        </tbody>\n      </table>","frequence":0},{"id":"109-3","rang":"B","rubrique":"Diagnostic positif","titre":"Connaître les échelles d’analyse de l’équilibre et de la marche (examen clinique, démarche diagnostique)","contenu":"<p>Les <span class=\"kw-clinique\">échelles d'analyse</span> de l'équilibre et de la marche complètent l'examen clinique : elles permettent un <span class=\"kw-def\">suivi</span> <strong>quantifié</strong> et reproductible.</p>\n      <table >\n        <thead><tr><th>Échelle / test</th><th>Ce qu'il évalue</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-clinique\">Échelle d'équilibre de Berg</span></td><td>Équilibre statique et dynamique sur une série d'épreuves cotées.</td></tr>\n          <tr><td><span class=\"kw-clinique\">Timed Up and Go (TUG)</span></td><td>Temps pour se lever d'une chaise, marcher, faire demi-tour et se rasseoir — mobilité globale.</td></tr>\n          <tr><td><span class=\"kw-clinique\">Périmètre de marche</span></td><td>Distance maximale parcourue — retentissement fonctionnel.</td></tr>\n          <tr><td><span class=\"kw-clinique\">Vitesse sur 10 mètres</span></td><td>Vitesse de marche confortable / rapide.</td></tr>\n          <tr><td><span class=\"kw-clinique\">Test de marche de 6 minutes</span></td><td>Endurance à la marche.</td></tr>\n          <tr><td><span class=\"kw-clinique\">Functional Ambulation Classification</span></td><td><span class=\"kw-def\">Classification</span> du niveau d'autonomie à la marche.</td></tr>\n        </tbody>\n      </table>","frequence":2},{"id":"109-4","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les caractéristiques cliniques des principales étiologies des troubles de la marche","contenu":"<p>Cet objectif est le cœur de l'item 109 (⭐⭐⭐⭐⭐). Les troubles de la marche se rangent en grandes familles sémiologiques — ataxies, troubles déficitaires, apraxie, troubles hypo- et hyperkinétiques, causes douloureuses — chacune avec une signature clinique propre.</p>\n\n      <h4 style=\"margin:16px 0 6px;font-size:14px;color:#1f2937;\">1 · Les trois ataxies (atteinte de l'adaptation du tonus et de la coordination, hors <span class=\"kw-clinique\">déficit moteur</span>)</h4>\n      <table >\n        <thead><tr><th></th><th>Proprioceptive</th><th>Vestibulaire</th><th>Cérébelleuse</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-clinique\">Romberg</span></td><td>Positif, <strong>non latéralisé</strong></td><td>Positif, <strong>latéralisé</strong></td><td><strong>Négatif</strong></td></tr>\n          <tr><td><span class=\"kw-clinique\">Polygone de sustentation</span></td><td>Élargi</td><td>Non élargi</td><td>Élargi</td></tr>\n          <tr><td><span class=\"kw-clinique\">Réflexes posturaux</span></td><td>Normaux</td><td>Normaux</td><td>Normaux</td></tr>\n        </tbody>\n      </table>\n      <figure class=\"obj-figure\">\n        <svg class=\"atlas-fig\" viewBox=\"0 0 560 360\" role=\"img\" aria-label=\"Arbre d'orientation entre les trois ataxies à partir de deux discriminants cliniques. Devant une ataxie avec Romberg positif ou instabilité debout, on pose la première question : l'instabilité de Romberg est-elle aggravée à la fermeture des yeux ? Si non, il s'agit d'une ataxie cérébelleuse, dont le Romberg est négatif et qui élargit le polygone de sustentation. Si oui, l'origine est sensorielle et l'on pose la seconde question : les troubles sont-ils latéralisés, toujours du même côté ? Si non, c'est une ataxie proprioceptive, avec chute non latéralisée et polygone élargi. Si oui, c'est une ataxie vestibulaire, latéralisée du même côté, sans élargissement du polygone.\" style=\"height:auto;display:block;border-radius:8px\">\n          <rect class=\"fb-grey\" x=\"160\" y=\"8\" width=\"240\" height=\"42\" rx=\"6\"/>\n          <text class=\"tx-grey\" x=\"280\" y=\"26\" text-anchor=\"middle\" font-size=\"12.5\" font-weight=\"600\">Ataxie</text>\n          <text class=\"tx-grey\" x=\"280\" y=\"42\" text-anchor=\"middle\" font-size=\"10.5\">Romberg positif / instabilité debout</text>\n          <line class=\"ln\" x1=\"280\" y1=\"50\" x2=\"280\" y2=\"64\" stroke-width=\"2\"/>\n          <polygon class=\"ah\" points=\"280,70 275,62 285,62\"/>\n          <rect class=\"fb-blue\" x=\"170\" y=\"72\" width=\"220\" height=\"42\" rx=\"6\"/>\n          <text class=\"tx-blue\" x=\"280\" y=\"90\" text-anchor=\"middle\" font-size=\"11.5\" font-weight=\"600\">Romberg aggravé</text>\n          <text class=\"tx-blue\" x=\"280\" y=\"105\" text-anchor=\"middle\" font-size=\"11.5\" font-weight=\"600\">à la fermeture des yeux ?</text>\n          <line class=\"ln\" x1=\"280\" y1=\"114\" x2=\"280\" y2=\"128\" stroke-width=\"2\"/>\n          <line class=\"ln\" x1=\"110\" y1=\"128\" x2=\"450\" y2=\"128\" stroke-width=\"2\"/>\n          <line class=\"ln\" x1=\"110\" y1=\"128\" x2=\"110\" y2=\"146\" stroke-width=\"2\"/>\n          <polygon class=\"ah\" points=\"110,152 105,144 115,144\"/>\n          <line class=\"ln\" x1=\"450\" y1=\"128\" x2=\"450\" y2=\"146\" stroke-width=\"2\"/>\n          <polygon class=\"ah\" points=\"450,152 445,144 455,144\"/>\n          <text class=\"tx-muted\" x=\"130\" y=\"142\" text-anchor=\"start\" font-size=\"11\" font-weight=\"600\">NON</text>\n          <text class=\"tx-muted\" x=\"430\" y=\"142\" text-anchor=\"end\" font-size=\"11\" font-weight=\"600\">OUI (sensorielle)</text>\n          <rect class=\"fb-ok\" x=\"20\" y=\"154\" width=\"180\" height=\"74\" rx=\"6\"/>\n          <text class=\"tx-ok\" x=\"110\" y=\"176\" text-anchor=\"middle\" font-size=\"12.5\" font-weight=\"700\">Cérébelleuse</text>\n          <text class=\"tx-ok\" x=\"110\" y=\"196\" text-anchor=\"middle\" font-size=\"10.5\">Romberg négatif</text>\n          <text class=\"tx-ok\" x=\"110\" y=\"211\" text-anchor=\"middle\" font-size=\"10.5\">Polygone élargi</text>\n          <rect class=\"fb-blue\" x=\"345\" y=\"154\" width=\"200\" height=\"56\" rx=\"6\"/>\n          <text class=\"tx-blue\" x=\"445\" y=\"178\" text-anchor=\"middle\" font-size=\"11.5\" font-weight=\"600\">Latéralisation ?</text>\n          <text class=\"tx-blue\" x=\"445\" y=\"194\" text-anchor=\"middle\" font-size=\"10.5\">toujours du même côté</text>\n          <line class=\"ln\" x1=\"445\" y1=\"210\" x2=\"445\" y2=\"224\" stroke-width=\"2\"/>\n          <line class=\"ln\" x1=\"250\" y1=\"224\" x2=\"450\" y2=\"224\" stroke-width=\"2\"/>\n          <line class=\"ln\" x1=\"250\" y1=\"224\" x2=\"250\" y2=\"244\" stroke-width=\"2\"/>\n          <polygon class=\"ah\" points=\"250,250 245,242 255,242\"/>\n          <line class=\"ln\" x1=\"450\" y1=\"224\" x2=\"450\" y2=\"244\" stroke-width=\"2\"/>\n          <polygon class=\"ah\" points=\"450,250 445,242 455,242\"/>\n          <text class=\"tx-muted\" x=\"270\" y=\"238\" text-anchor=\"start\" font-size=\"11\" font-weight=\"600\">NON</text>\n          <text class=\"tx-muted\" x=\"430\" y=\"238\" text-anchor=\"end\" font-size=\"11\" font-weight=\"600\">OUI</text>\n          <rect class=\"fb-amber\" x=\"160\" y=\"252\" width=\"180\" height=\"92\" rx=\"6\"/>\n          <text class=\"tx-amber\" x=\"250\" y=\"274\" text-anchor=\"middle\" font-size=\"12.5\" font-weight=\"700\">Proprioceptive</text>\n          <text class=\"tx-amber\" x=\"250\" y=\"294\" text-anchor=\"middle\" font-size=\"10.5\">Chute non latéralisée</text>\n          <text class=\"tx-amber\" x=\"250\" y=\"309\" text-anchor=\"middle\" font-size=\"10.5\">Polygone élargi</text>\n          <text class=\"tx-amber\" x=\"250\" y=\"324\" text-anchor=\"middle\" font-size=\"10.5\">Marche talonnante</text>\n          <rect class=\"fb-red\" x=\"360\" y=\"252\" width=\"185\" height=\"92\" rx=\"6\"/>\n          <text class=\"tx-red\" x=\"452\" y=\"274\" text-anchor=\"middle\" font-size=\"12.5\" font-weight=\"700\">Vestibulaire</text>\n          <text class=\"tx-red\" x=\"452\" y=\"294\" text-anchor=\"middle\" font-size=\"10.5\">Latéralisée même côté</text>\n          <text class=\"tx-red\" x=\"452\" y=\"309\" text-anchor=\"middle\" font-size=\"10.5\">Polygone non élargi</text>\n          <text class=\"tx-red\" x=\"452\" y=\"324\" text-anchor=\"middle\" font-size=\"10.5\">Marche en étoile</text>\n        </svg>\n        <figcaption>Deux discriminants suffisent à trier les trois ataxies : l'aggravation du Romberg à la fermeture des yeux (origine sensorielle), puis la latéralisation. Schéma statique fondé sur la trame de l'item.</figcaption>\n      </figure>\n      <ul>\n        <li><strong>Ataxie proprioceptive :</strong> Romberg très perturbé, nettement aggravé à la fermeture des yeux, chute non latéralisée ; polygone élargi ; <span class=\"kw-clinique\">marche talonnante</span> (jambe lancée trop haut, appui mal contrôlé). Étiologies : <span class=\"kw-etio\">maladie de Biermer</span>, <span class=\"kw-etio\">syndromes paranéoplasiques</span>, <span class=\"kw-etio\">tabès</span> (syphilis tertiaire), <span class=\"kw-etio\">neuropathies inflammatoires</span> (IgM monoclonale, polyradiculonévrites).</li>\n        <li><strong>Ataxie cérébelleuse</strong> (<span class=\"kw-def\">syndrome cérébelleux</span> statique) : élargissement du polygone avec oscillations en tous sens, <span class=\"kw-clinique\">danse des tendons</span> (contraction incessante des jambiers antérieurs), tenue impossible pieds joints, marche pseudo-ébrieuse ; <span class=\"kw-alerte\">non aggravée à l'occlusion des yeux ⭐</span>, pas de latéralisation. Formes mineures : arrêt brusque déstabilisant, marche funambule festonnée, demi-tour décomposé.</li>\n        <li><strong>Ataxie vestibulaire :</strong> troubles posturaux et de la marche latéralisés toujours du même côté, aggravés à la fermeture des yeux ; manœuvre des index déviée &gt; <span class=\"kw-chiffre\">30°</span> ; marche aveugle « en étoile » ; manœuvre de Fukuda déviée &gt; <span class=\"kw-chiffre\">60°</span> ; <strong>pas d'élargissement du polygone</strong> de sustentation.</li>\n      </ul>\n\n      <h4 style=\"margin:16px 0 6px;font-size:14px;color:#1f2937;\">2 · Troubles moteurs déficitaires</h4>\n      <table >\n        <thead><tr><th>Type</th><th>Mécanisme et étiologies</th></tr></thead>\n        <tbody>\n          <tr><td>Marche steppante (<span class=\"kw-clinique\">steppage</span>)</td><td><strong>Mécanisme :</strong> défaut de dorsiflexion du pied par déficit du jambier antérieur → « pied tombant », genou levé trop haut à chaque pas.<br><strong>Étiologies :</strong> atteinte du nerf <span class=\"kw-etio\">fibulaire commun</span>, atteinte <span class=\"kw-etio\">L4-L5</span>, polyneuropathies (<span class=\"kw-etio\">Charcot-Marie-Tooth</span>), <span class=\"kw-etio\">SLA</span>, <span class=\"kw-etio\">myopathie</span>.</td></tr>\n          <tr><td>Marche fauchante (<span class=\"kw-clinique\">fauchage</span>)</td><td><strong>Mécanisme :</strong> <span class=\"kw-def\">syndrome pyramidal</span> — membre inférieur en triple extension, pied en varus équin, circumduction (demi-cercle au sol).<br><strong>Étiologies :</strong> unilatéral → <span class=\"kw-etio\">AVC</span>, traumatisme crânien, <span class=\"kw-clinique\">hémiplégie</span> infantile ; bilatéral (marche « en ciseaux », paraparésie spastique) → atteinte médullaire (<span class=\"kw-etio\">SEP</span>, <span class=\"kw-etio\">myélite</span>, <span class=\"kw-etio\">compression médullaire</span>).</td></tr>\n          <tr><td>Boiterie de Trendelenburg</td><td><strong>Mécanisme :</strong> faiblesse du <strong><span class=\"kw-etio\">moyen fessier</span></strong> → abaissement du bassin du côté non portant ; si bilatérale → démarche dandinante.<br><strong>Étiologies :</strong> neurologique (atteinte <span class=\"kw-etio\">L5</span>), musculaire (<span class=\"kw-etio\">myopathie</span>), orthopédique (<span class=\"kw-etio\">coxarthrose</span>).</td></tr>\n          <tr><td>Marche dandinante</td><td><strong>Mécanisme :</strong> déficit de la ceinture pelvienne et des muscles proximaux des membres inférieurs → « marche en canard », bascule du bassin à chaque pas ; montée d'escalier et relevé difficiles.<br><strong>Étiologies :</strong> <span class=\"kw-etio\">syndromes myogènes</span>, <span class=\"kw-etio\">neuropathies motrices proximales</span>.</td></tr>\n          <tr><td><span class=\"kw-clinique\">Boiterie avec salutation</span></td><td><strong>Mécanisme :</strong> flexion antérieure du tronc en phase d'appui (« comme pour saluer »).<br><strong>Causes :</strong> défaut d'extension de hanche (rétraction des fléchisseurs, coxopathie) ou perte de force du quadriceps.</td></tr>\n        </tbody>\n      </table>\n\n      <h4 style=\"margin:16px 0 6px;font-size:14px;color:#1f2937;\">3 · Apraxie de la marche</h4>\n      <p>Perturbation du <span class=\"kw-def\">schéma moteur</span> : les séquences gestuelles sont correctement coordonnées mais ne s'associent plus vers le but choisi. Cliniquement : élargissement du polygone, tendance à la rétropulsion, <span class=\"kw-def\">astasie-abasie</span> au maximum. Étiologies : <span class=\"kw-etio\">lésion frontale</span>, <span class=\"kw-etio\">hydrocéphalie chronique de l'adulte</span>, <span class=\"kw-etio\">état lacunaire</span>.</p>\n\n      <h4 style=\"margin:16px 0 6px;font-size:14px;color:#1f2937;\">4 · Troubles moteurs hypokinétiques — marche à petits pas</h4>\n      <p><span class=\"kw-alerte\">Trouble de la marche le plus fréquent (1/3 des cas)</span> : diminution de la longueur d'enjambée, déficit primaire à l'origine de la perte de vitesse.</p>\n      <table >\n        <thead><tr><th>Étiologie</th><th>Caractéristiques</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-etio\">Hydrocéphalie chronique de l'adulte</span></td><td>Marche à petits pas, apraxie de la marche.</td></tr>\n          <tr><td><span class=\"kw-etio\">États lacunaires</span></td><td><span class=\"kw-def\">Terrain</span> : <span class=\"kw-clinique\">HTA</span> sévère instable, <span class=\"kw-clinique\">infarctus</span> multiples ; <span class=\"kw-clinique\">évolution</span> <strong>par poussées</strong> ; marche à petits pas ± freezing ; syndrome pseudo-bulbaire (rire/pleurs spasmodiques, diplégie faciale, troubles sphinctériens, troubles de la déglutition/phonation), troubles cognitifs frontaux, anomalies sévères des réflexes posturaux.</td></tr>\n          <tr><td><span class=\"kw-etio\">Syndromes parkinsoniens</span></td><td>Parkinson débutant : enjambée réduite, <strong>prédominance sur un hémicorps</strong>, perte du ballant d'un bras, très bonne dopa-sensibilité, marche normalisable par effort de volonté (perdue dans les formes tardives). Formes tardives : <span class=\"kw-clinique\">freezing</span> (enrayage cinétique), <span class=\"kw-clinique\">festination</span>, chutes en avant.</td></tr>\n          <tr><td><span class=\"kw-etio\">Phobie de la chute</span></td><td>Sidération des automatismes de l'équilibre et de la marche — voir l'objectif « syndrome post-chute ».</td></tr>\n          <tr><td><span class=\"kw-etio\">Marche précautionneuse</span></td><td>Marche ralentie, prudente, <strong>sans déficit majeur</strong> ; sujet âgé, prédominance féminine ; recherche d'appuis et besoin de réassurance.</td></tr>\n        </tbody>\n      </table>\n\n      <h4 style=\"margin:16px 0 6px;font-size:14px;color:#1f2937;\">5 · Troubles moteurs hyperkinétiques (mouvements anormaux)</h4>\n      <table >\n        <thead><tr><th>Type</th><th>Caractéristiques</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-etio\">Dystonie</span></td><td><span class=\"kw-alerte\">Mouvement anormal le plus pourvoyeur de troubles de la marche</span> : pseudo-steppage, « marche en héron » (élévation des genoux), « marche de dromadaire » (flexion-extension alternée du tronc). Test de dopa-sensibilité à réaliser.</td></tr>\n          <tr><td><span class=\"kw-etio\">Chorée</span></td><td><strong>Dyskinésies</strong> induites par la <span class=\"kw-ttt\">lévodopa</span> dans la maladie de <span class=\"kw-etio\">Parkinson</span>. Chorée de Huntington : atteinte sévère des réflexes posturaux, mouvements choréodystoniques, marche souvent perdue en cours d'<span class=\"kw-clinique\">évolution</span>, chutes fréquentes.</td></tr>\n          <tr><td><span class=\"kw-etio\">Tremblement essentiel</span></td><td>Discret trouble de l'équilibre proche du <span class=\"kw-def\">syndrome cérébelleux</span>, peu symptomatique.</td></tr>\n          <tr><td><span class=\"kw-etio\">Tremblement orthostatique</span></td><td>Tremblement de fréquence élevée (<span class=\"kw-chiffre\">14-18 Hz</span>) touchant les membres inférieurs ; sensation d'instabilité / dérobement en station debout immobile ; objectivé par <span class=\"kw-clinique\">EMG des membres inférieurs en position debout</span>.</td></tr>\n        </tbody>\n      </table>\n\n      <h4 style=\"margin:16px 0 6px;font-size:14px;color:#1f2937;\">6 · Étiologies douloureuses et marches psychogènes</h4>\n      <ul>\n        <li><span class=\"kw-clinique\">Boiterie d'esquive</span> : évitement de l'appui du côté douloureux.</li>\n        <li><span class=\"kw-clinique\">Claudication intermittente</span> (véritable limitation de la marche) : <span class=\"kw-etio\">AOMI</span>, <span class=\"kw-etio\">canal lombaire étroit</span>, cause articulaire.</li>\n        <li><span class=\"kw-clinique\">Myalgies</span> d'effort + <strong>phénomène du <span class=\"kw-def\">second souffle</span></strong> : très spécifiques d'une <span class=\"kw-etio\">maladie de McArdle</span> (glycogénose musculaire).</li>\n        <li><span class=\"kw-clinique\">Marches psychogènes</span> : jusqu'à <span class=\"kw-chiffre\">10 %</span> des patients — prototypes caricaturaux, installation brutale, incohérences à l'examen, examens complémentaires normaux.</li>\n      </ul>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 104 — SEP · 106 — Parkinson · 107 — Mouvements anormaux · 340 — <span class=\"kw-etio\">AVC</span> · 96 — Neuropathie périphérique · 97 — Polyradiculonévrite aigue <span class=\"kw-etio\">inflammatoire</span> · 95 — Radiculalgie - Syndrome canalaire</em></p>","frequence":5,"liens":[{"href":"https://www.youtube.com/watch?v=HJ4zuY_9JFw","label":"YouTube — Ataxie cérébelleuse"},{"href":"https://www.cen-neurologie.fr/videotheque/deviations-toniques-axiales-index-marche-aveugle-etoile","label":"CEN Vidéothèque — Déviations toniques axiales (ataxie vestibulaire)"},{"href":"https://radiopaedia.org/articles/lacunar-infarct","label":"Radiopaedia : Lacunar infarct (états lacunaires)"}]},{"id":"109-5","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les modalités du uiagnostic d’une boiterie (examen clinique, démarche diagnostique)","contenu":"<p>L'analyse d'une <span class=\"kw-clinique\">boiterie</span> repose sur l'identification de la <strong>phase du cycle de marche</strong> perturbée, puis sur son rattachement à un grand mécanisme.</p>\n      <table >\n        <thead><tr><th>Type de boiterie</th><th>Mécanisme orientant</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-clinique\">Boiterie d'esquive</span></td><td><strong>Douleur :</strong> raccourcissement du temps d'appui sur le <span class=\"kw-clinique\">côté douloureux</span>.</td></tr>\n          <tr><td><span class=\"kw-clinique\">Boiterie d'équilibration (Trendelenburg)</span></td><td>Faiblesse du <span class=\"kw-etio\">moyen fessier</span> : <span class=\"kw-clinique\">abaissement du bassin du côté non portant</span>, inclinaison compensatrice du tronc.</td></tr>\n          <tr><td><span class=\"kw-clinique\">Boiterie avec salutation</span></td><td>Défaut d'extension de <span class=\"kw-etio\">hanche</span> ou perte de force du quadriceps : <span class=\"kw-clinique\">flexion antérieure du tronc en phase d'appui</span>.</td></tr>\n          <tr><td><span class=\"kw-clinique\">Boiterie par inégalité de longueur</span></td><td><span class=\"kw-etio\">Asymétrie de longueur</span> des membres inférieurs.</td></tr>\n          <tr><td><span class=\"kw-clinique\">Boiterie déficitaire</span></td><td><span class=\"kw-clinique\">Steppage</span>, <span class=\"kw-clinique\">fauchage</span> — <span class=\"kw-clinique\">déficit moteur</span> <span class=\"kw-etio\">tronculaire, radiculaire ou pyramidal</span>.</td></tr>\n        </tbody>\n      </table>\n      <p>La démarche se croise avec l'examen <strong>cinématique articulaire</strong> (cheville, genou, hanche, tronc) détaillé dans l'objectif « modalités de l'examen ».</p>\n      <div class=\"callout callout-warn\">⚠️ <strong>À compléter.</strong> La fiche source ne détaille pas spécifiquement la « démarche diagnostique d'une boiterie » au-delà des grands types ci-dessus. Kevin complétera (orthopédie / MPR) si besoin.</div>\n      <!-- TODO Kevin : démarche diagnostique détaillée d'une boiterie (MPR / orthopédie) -->","frequence":0},{"id":"109-6","rang":"A","rubrique":"Définition","titre":"Connaître la définition de l’astasie-abasie","contenu":"<p>L'<span class=\"kw-def\">astasie-abasie</span> représente le <strong>maximum de l'apraxie de la marche</strong> : le patient est incapable de tenir debout ou de marcher.</p>\n      <ul>\n        <li><span class=\"kw-def\">Astasie</span> : <strong>instabilité à la station debout avec <span class=\"kw-clinique\">rétropulsion spontanée</span></strong>.</li>\n        <li><span class=\"kw-def\">Abasie</span> : <strong>incapacité à marcher en dehors de la présence de tout <span class=\"kw-def\">syndrome pyramidal</span> ou parkinsonien</strong>.</li>\n      </ul>","frequence":0},{"id":"109-7","rang":"B","rubrique":"Etiologies","titre":"Connaître les étiologies de l’astasie-abasie","contenu":"<p>Les étiologies de l'astasie-abasie recoupent celles de l'<span class=\"kw-def\">apraxie de la marche</span>, dont elle est la forme extrême.</p>\n      <ul>\n        <li><span class=\"kw-etio\">Lésion frontale</span>.</li>\n        <li><span class=\"kw-etio\">Hydrocéphalie chronique de l'adulte</span>.</li>\n        <li><span class=\"kw-etio\">État lacunaire</span>.</li>\n        <li><span class=\"kw-etio\">Astasie-abasie pure</span> — retenue lorsqu'aucune cause n'est apparente.</li>\n      </ul>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 340 — <span class=\"kw-etio\">AVC</span></em></p>","frequence":0},{"id":"109-8","rang":"B","rubrique":"Etiologies","titre":"Connaître l’étiologie des démarches dandinantes","contenu":"<p>La <span class=\"kw-clinique\">démarche dandinante</span> (« marche en canard ») témoigne d'un <strong><span class=\"kw-clinique\">déficit moteur</span> de la ceinture pelvienne</strong> et des muscles proximaux des membres inférieurs : inclinaison latérale du tronc du côté du membre portant, bascule du bassin d'un côté et de l'autre à chaque pas.</p>\n      <ul>\n        <li><span class=\"kw-etio\">Syndromes myogènes / myopathies</span> — atteinte musculaire proximale.</li>\n        <li><span class=\"kw-etio\">Neuropathies motrices proximales</span> — ex. neuropathie motrice proximale amyotrophiante du <span class=\"kw-def\">diabète</span>.</li>\n      </ul>\n      <p>Une <span class=\"kw-clinique\">boiterie de Trendelenburg bilatérale</span> aboutit également à une démarche dandinante.</p>","frequence":0},{"id":"109-9","rang":"A","rubrique":"Etiologies","titre":"Connaître le syndrome post chute","contenu":"<p>Le <span class=\"kw-def\">syndrome post-chute</span> (ou phobie de la chute) correspond à une véritable <strong>sidération des automatismes de l'équilibre et de la marche</strong>.</p>\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Caractéristiques</h4>\n      <ul>\n        <li>Cause <strong>non expliquée</strong> par d'éventuelles lésions traumatiques ou neurologiques de la chute, et <strong>non corrélée</strong> au caractère traumatisant ou à la fréquence de la chute.</li>\n        <li>D'autant plus marqué que le <span class=\"kw-alerte\">sujet est resté longtemps au sol</span>.</li>\n      </ul>\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Manifestations</h4>\n      <ul>\n        <li><span class=\"kw-clinique\">Rétropulsion</span> rendant la station debout impossible sans aide humaine (tendance rétropulsive lors du lever ; dans les formes vieillies : appui talonnier et <span class=\"kw-clinique\">orteils en griffe</span>).</li>\n        <li><span class=\"kw-clinique\">Phobie de la marche, voire de la verticalisation (stasobasophobie)</span> : composante anxieuse majeure, agrippement à l'examinateur ou au mobilier, réactions anxieuses majeures à toute tentative de lâcher le sujet.</li>\n        <li>Marche avec aide humaine : petits pas glissés en appui talonnier sans déroulement du pas, retard d'initiation / freezing.</li>\n        <li><span class=\"kw-clinique\">Hypertonie oppositionnelle</span> ; altération des réactions d'adaptation posturale et des réactions parachutes.</li>\n      </ul>\n      <div class=\"callout callout-danger\">🔥 <strong><span class=\"kw-alerte\">Urgence</span> gériatrique.</strong> <span class=\"kw-clinique\">Évolution</span> <strong>réversible</strong> si prise en charge précoce ; <span class=\"kw-alerte\">mauvais pronostic fonctionnel</span> sans PEC rapide (évolution inexorable vers la perte d'autonomie complète). CAT : <span class=\"kw-ttt\">hospitalisation</span> — <span class=\"kw-ttt\">rééducation fonctionnelle</span> et soutien psychologique (les psychotropes ont peu d'effet).</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 131 — Troubles de la marche et de l'équilibre du sujet âgé</em></p>","frequence":0},{"id":"109-10","rang":"B","rubrique":"Etiologies","titre":"Savoir évoquer une étiologie somato-fonctionnelle devant un trouble de la marche et/ou de l’équilibre","contenu":"<p>Une <strong>étiologie somato-fonctionnelle</strong> (trouble de la marche <span class=\"kw-clinique\">psychogène</span>) doit être évoquée devant un trouble de la marche et/ou de l'équilibre. Elle est relativement fréquente — jusqu'à <span class=\"kw-chiffre\">~10 %</span> des patients de cette catégorie.</p>\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Arguments d'orientation</h4>\n      <ul>\n        <li>Reproduction des <strong>prototypes de marche pathologique</strong>, parfois de façon <strong>caricaturale</strong> (marche hémiplégique, marche ataxique…).</li>\n        <li><span class=\"kw-clinique\">Installation brutale</span>.</li>\n        <li><span class=\"kw-clinique\">Incohérences à l'examen clinique</span>.</li>\n        <li><span class=\"kw-clinique\">Normalité des examens complémentaires</span> — permet en général de poser le diagnostic.</li>\n      </ul>\n      <div class=\"callout callout-warn\">⚠️ Diagnostic évoqué <strong>par élimination</strong> : la normalité du bilan oriente, mais une cause organique doit avoir été raisonnablement écartée — <span class=\"kw-ci\">ne jamais</span> l'affirmer d'emblée.</div>","frequence":0},{"id":"109-11","rang":"B","rubrique":"Contenu multimédia","titre":"Reconnaître les principaux troubles de la marche devant un cas vidéo","contenu":"<p>Cet objectif relève du <strong>contenu multimédia</strong> : reconnaître un trouble de la marche sur un <span class=\"kw-clinique\">cas vidéo</span>. Voici la grille de lecture visuelle synthétique des principaux troubles.</p>\n      <table >\n        <thead><tr><th>À l'œil, on cherche…</th><th>Trouble évoqué</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-clinique\">Élargissement du polygone</span>, oscillations en tous sens, marche pseudo-ébrieuse</td><td>Ataxie cérébelleuse</td></tr>\n          <tr><td>Instabilité <strong>latéralisée toujours du même côté</strong>, aggravée yeux fermés</td><td>Ataxie vestibulaire</td></tr>\n          <tr><td><span class=\"kw-clinique\">Marche talonnante</span>, regard au sol, nette aggravation yeux fermés</td><td>Ataxie proprioceptive</td></tr>\n          <tr><td><span class=\"kw-clinique\">Steppage</span> : genou levé haut, pied tombant</td><td>Déficit des releveurs (fibulaire commun, L4-L5)</td></tr>\n          <tr><td><span class=\"kw-clinique\">Fauchage</span> : circumduction du membre, pied en varus équin</td><td><span class=\"kw-def\">Syndrome pyramidal</span></td></tr>\n          <tr><td><span class=\"kw-clinique\">Marche à petits pas</span>, freezing, <span class=\"kw-clinique\">festination</span>, perte du ballant d'un bras</td><td>Syndrome parkinsonien / trouble hypokinétique</td></tr>\n          <tr><td>« Marche en canard », bascule du bassin à chaque pas</td><td>Démarche dandinante (déficit pelvien)</td></tr>\n          <tr><td><span class=\"kw-clinique\">Danse des tendons</span> debout, rétropulsion</td><td><span class=\"kw-def\">Syndrome cérébelleux</span> / apraxie de la marche</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\">\n        <strong>À compléter.</strong> Cet objectif « Contenu multimédia » repose sur la reconnaissance vidéo. Les fiches sources renvoient à des vidéos (cen-neurologie, YouTube) non intégrables hors-ligne. Kevin ajoutera ici les captures/GIF pertinents ou les liens validés.\n      </div>\n      <!-- TODO Kevin : vidéos/captures de reconnaissance des marches -->","frequence":0},{"id":"109-12","rang":"A","rubrique":"Examens complémentaires","titre":"Connaître l’indication et l’intérêt des examens d’imagerie devant un trouble de la marche ou de l’équilibre","contenu":"<p>L'imagerie devant un trouble de la marche ou de l'équilibre est <span class=\"kw-alerte\">orientée par la clinique</span> — elle n'est pas systématique. Le choix de la cible découle de l'interrogatoire et de l'examen.</p>\n      <table >\n        <thead><tr><th>Examen</th><th>Indication / intérêt</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-imagerie\">IRM de la moelle spinale</span></td><td>Suspicion de <span class=\"kw-etio\">compression médullaire</span>, de <span class=\"kw-etio\">myélopathie</span>, d'<span class=\"kw-etio\">atteinte cordonale postérieure</span>.</td></tr>\n          <tr><td><span class=\"kw-imagerie\">IRM cérébrale</span></td><td>Suspicion de <span class=\"kw-etio\">SEP</span>, d'<span class=\"kw-etio\">hydrocéphalie chronique de l'adulte</span>, de <span class=\"kw-etio\">lésion frontale</span>, d'<span class=\"kw-etio\">AVC / état lacunaire</span>, de <span class=\"kw-etio\">tumeur cérébrale</span>.</td></tr>\n        </tbody>\n      </table>\n      <p>La décision même d'imager, comme le choix moelle <span class=\"kw-bio\">vs</span> cerveau, dépend de l'<strong>orientation clinique</strong> préalable.</p>","frequence":0},{"id":"109-13","rang":"A","rubrique":"Examens complémentaires","titre":"Citer les principaux examens complémentaires hors imagerie devant un trouble de la marche ou de l’équilibre","contenu":"<p>En dehors de l'imagerie, plusieurs examens complémentaires explorent un trouble de la marche ou de l'équilibre, demandés <strong>selon le contexte clinique</strong>.</p>\n      <table >\n        <thead><tr><th>Examen</th><th>Indication / intérêt</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-clinique\">Électromyogramme (EMG)</span></td><td>Neuropathies, myopathies, <span class=\"kw-etio\">SLA</span> ; <span class=\"kw-etio\">tremblement orthostatique</span> (<span class=\"kw-imagerie\">EMG</span> des membres inférieurs réalisé en position debout immobile).</td></tr>\n          <tr><td><span class=\"kw-clinique\">Examen audiovestibulaire</span></td><td>Suspicion d'<span class=\"kw-etio\">ataxie vestibulaire</span>.</td></tr>\n          <tr><td><span class=\"kw-clinique\">Analyse quantifiée de la marche</span></td><td>Réalisable dans certains centres spécialisés : longueur et durée des cycles, <span class=\"kw-clinique\">asymétrie</span> du pas.</td></tr>\n          <tr><td><span class=\"kw-ttt\">Test de soustraction du LCS</span></td><td>Test thérapeutique — suspicion d'<span class=\"kw-etio\">hydrocéphalie à pression normale</span>.</td></tr>\n          <tr><td><span class=\"kw-ttt\">Test à la lévodopa</span></td><td>Test thérapeutique — devant une marche à petits pas ou une dystonie, à la recherche d'une <strong>dopa-sensibilité</strong>.</td></tr>\n        </tbody>\n      </table>","frequence":0}],"astuces":[{"type":"danger","titre":"Fracture du col fémoral chez le sujet âgé qui chute","contenu":"Devant toute chute chez une personne âgée avec impotence fonctionnelle de la hanche, douleur inguinale ou latérale, ou rotation externe du membre = radiographie de hanche systématique. Ne pas se fier à l'absence de douleur (formes décollées)."},{"type":"warn","titre":"Le test de Romberg et ses pièges","contenu":"Romberg positif (instabilité majorée à la fermeture des yeux) = atteinte de la sensibilité profonde (voies postérieures, neuropathie sensitivo-motrice). Romberg négatif avec instabilité yeux ouverts ET fermés = atteinte cérébelleuse. Un Romberg faux-positif peut exister chez le sujet anxieux."},{"type":"info","titre":"Myélopathie cervicale = démarche spastique + troubles des mains","contenu":"La myélopathie cervicale compressive se présente souvent par une démarche spastique 'en clou' associée à une faiblesse distale des membres supérieurs (myélopathie manique). L'IRM cervicale est l'examen de référence. Penser à la vitamine B12 devant une myélopathie subaiguë combinée."},{"type":"tip","titre":"TUG et Tinetti : dépistage rapide du risque de chute","contenu":"Le Timed Up and Go (TUG) < 10 secondes est normal ; > 20 secondes = risque de chute élevé. Le Tinetti < 19 = risque élevé. Ces tests sont rapides, ne nécessitent pas de matériel coûteux, et doivent être réalisés systématiquement chez le sujet âgé."},{"type":"warn","titre":"Astasie-abasie : magnétisme des pieds vs conversion","contenu":"Le magnétisme des pieds (pieds collés au sol, impossibilité de les soulever malgré force conservée) évoque un syndrome frontal ou une hydrocéphalie (cause organique). La conversion se distingue par une motricité normale au lit et des chutes non protectrices. L'IRM cérébrale élimine la cause organique."},{"type":"info","titre":"Neuropathie périphérique : toujours chercher la cause","contenu":"Une neuropathie périphérique n'est pas idiopathique par défaut. Bilan étiologique : diabète, alcool, vitamine B12, médicaments (vincristine, isoniazide, métroNIDAZOLE), hémopathie (myélome, lymphome), maladie de Charcot-Marie-Tooth, VIH, hépatite C, amylose."}],"strategie":{"principes":"<p><em>Stratégie de prise en charge à compléter — non disponible dans la source GitHub pour cet item.</em></p>"},"liensGlobaux":[{"href":"https://www.cen-neurologie.fr/second-cycle/troubles-de-la-marche-et-de-lequilibre-troubles-de-la-marche-et-de-lequilibre-chez-le-sujet-age","label":"Collège CEN — Troubles marche & équilibre"},{"href":"https://www.youtube.com/watch?v=ncrZ5G-8z5Q&t=3s","label":"YouTube — Physiologie de la marche"}],"arbre":{"rootId":"root","nodes":[{"id":"root","kind":"root","label":"Ataxie — Romberg positif ou instabilité debout — Premier discriminant : l'instabilité du Romberg s'aggrave-t-elle à la fermeture des yeux ?","detail":"<h4>Orientation des trois ataxies — Démarche diagnostique devant une ataxie / un trouble de l'équilibre</h4>","branches":[{"to":"t-cerebelleuse","label":"Non — non aggravé à l'occlusion des yeux","color":"green"},{"to":"q-lateralisation","label":"Oui — aggravation à la fermeture des yeux (origine sensorielle)","color":"amber"}]},{"id":"t-cerebelleuse","kind":"terminal","label":"Ataxie cérébelleuse (syndrome cérébelleux statique)","color":"green","detail":"<h4>Romberg</h4><ul><li><span class=\"kw-clinique\">Romberg négatif</span> : signes <strong>non aggravés</strong> à l'occlusion des yeux (point clé ⭐), <span class=\"kw-clinique\">pas de latéralisation</span>, <span class=\"kw-clinique\">réflexes posturaux normaux</span>.</li></ul><h4>Équilibre debout</h4><ul><li><span class=\"kw-clinique\">Élargissement du polygone de sustentation</span>, oscillations en tous sens</li><li><span class=\"kw-clinique\">Danse des tendons</span> (contraction incessante des jambiers antérieurs)</li><li>Tenue <strong>impossible pieds joints</strong></li></ul><h4>Marche</h4><ul><li><span class=\"kw-clinique\">Marche pseudo-ébrieuse</span> : polygone élargi, bras écartés du thorax, enjambées irrégulières, pieds jetés trop hauts, embardées.</li></ul><h4>Formes mineures</h4><ul><li><span class=\"kw-clinique\">Arrêt brusque</span> qui déstabilise</li><li><span class=\"kw-clinique\">Marche en funambule</span> festonnée</li><li><span class=\"kw-clinique\">Demi-tour décomposé</span></li></ul><h4>Localisation</h4><ul><li>Atteinte du <span class=\"kw-def\">vermis cérébelleux</span> (régulation de la statique) ou du <span class=\"kw-def\">pédoncule cérébelleux inférieur</span>.</li></ul>"},{"id":"q-lateralisation","kind":"decision","label":"Les troubles sont-ils latéralisés, toujours du même côté ? — La latéralisation constante sépare l'ataxie vestibulaire de l'ataxie proprioceptive.","branches":[{"to":"t-proprioceptive","label":"Non — chute non latéralisée","color":"amber"},{"to":"t-vestibulaire","label":"Oui — toujours du même côté","color":"red"}]},{"id":"t-proprioceptive","kind":"terminal","label":"Ataxie proprioceptive","color":"amber","detail":"<h4>Romberg</h4><ul><li><span class=\"kw-clinique\">Romberg très perturbé</span>, <strong>nettement aggravé à la fermeture des yeux</strong>, <span class=\"kw-clinique\">chute non latéralisée</span> ; <span class=\"kw-clinique\">polygone élargi</span> ; <span class=\"kw-clinique\">réflexes posturaux normaux</span>.</li></ul><h4>Marche</h4><ul><li><span class=\"kw-clinique\">Marche talonnante</span> : jambe lancée trop haut, appui au sol mal contrôlé (contact parfois violent).</li></ul><h4>Localisation</h4><ul><li>Voies proprioceptives périphériques : <span class=\"kw-def\">fibres sensitives myélinisées de grand calibre</span>, <span class=\"kw-def\">ganglion spinal</span></li><li>Voies centrales : <span class=\"kw-def\">cordons postérieurs</span> de la moelle spinale et relais</li></ul><h4>Étiologies</h4><ul><li><span class=\"kw-etio\">Maladie de Biermer</span> (carence en <span class=\"kw-bio\">vitamine B12</span>)</li><li><span class=\"kw-etio\">Syndromes paranéoplasiques</span></li><li><span class=\"kw-etio\">Tabès</span> (syphilis tertiaire)</li><li><span class=\"kw-etio\">Neuropathies inflammatoires</span> (IgM monoclonale, polyradiculonévrites)</li></ul>"},{"id":"t-vestibulaire","kind":"terminal","label":"Ataxie vestibulaire","color":"red","detail":"<h4>Caractère</h4><ul><li>Troubles posturaux et de la marche <strong>latéralisés toujours du même côté</strong>, aggravés à la fermeture des yeux. Syndrome vestibulaire intense : <span class=\"kw-clinique\">station debout et marche impossibles</span>.</li></ul><h4>Romberg</h4><ul><li><span class=\"kw-clinique\">Inclinaison latérale lente</span> de l'axe du corps après quelques secondes d'occlusion des yeux ; déviation <strong>toujours du même côté</strong> (côté sain ou pathologique).</li></ul><h4>Manœuvres</h4><ul><li>Manœuvre des index : déviation <span class=\"kw-chiffre\">&gt; 30°</span> dans le plan horizontal, du même côté que le Romberg</li><li>Marche aveugle : déplacement <span class=\"kw-clinique\">« en étoile »</span> (3 pas avant / 3 pas arrière, yeux fermés)</li><li>Manœuvre de Fukuda : déviation / rotation <span class=\"kw-chiffre\">&gt; 60°</span> ou chute</li></ul><h4>Point clé</h4><ul><li><strong>Pas d'élargissement du polygone de sustentation</strong> (≠ ataxies proprioceptive et cérébelleuse).</li></ul>"}]},"cards":[{"i":"10a93989cc07","n":109,"o":"109-1","u":"Diagnostic positif","t":"Connaître les éléments de l’interrogatoire devant un trouble de la marche","q":"Quels sont les éléments clés à documenter lors de l'interrogatoire concernant la chronologie d'un trouble de la marche ?","a":"<p>Il est essentiel de préciser :</p><ul><li>La <strong>date de début</strong> des troubles.</li><li>Le <strong>mode d'installation</strong> des troubles (brutal, progressif, par poussées).</li></ul>"},{"i":"1c1581931b6b","n":109,"o":"109-1","u":"Diagnostic positif","t":"Connaître les éléments de l’interrogatoire devant un trouble de la marche","q":"Quels sont les principaux types de plaintes que doit rechercher le clinicien lors de l'interrogatoire d'un patient présentant un trouble de la marche ?","a":"<p>Le clinicien doit rechercher des plaintes spécifiques, notamment :</p><ul><li>La <strong>douleur</strong> et sa relation avec l'effort.</li><li>La <strong>faiblesse</strong>.</li><li>L'<strong>instabilité</strong> (à bien différencier d'un vertige).</li><li>Les <strong>petits pas</strong>.</li><li>La <strong>raideur</strong>.</li></ul>"},{"i":"d2d63f35caa2","n":109,"o":"109-1","u":"Diagnostic positif","t":"Connaître les éléments de l’interrogatoire devant un trouble de la marche","q":"Quels sont les indicateurs de sévérité du trouble de la marche à rechercher lors de l'interrogatoire ?","a":"<p>Les indicateurs de sévérité comprennent :</p><ul><li>La survenue de <strong>chutes ou « presque-chutes »</strong>.</li><li>Les <strong>conséquences en morbidité</strong> (traumatismes, fractures, hospitalisations).</li><li>Les <strong>conséquences sur l'autonomie</strong> (sorties non accompagnées avec/sans transports en commun, sorties accompagnées, absence de sortie du domicile).</li><li>La <strong>capacité à monter/descendre un escalier</strong> (monter teste la force, descendre teste l'équilibre).</li><li>L'autonomie pour les activités quotidiennes (ménage, cuisine, habillage, toilette).</li><li>L'<strong>usage d'une aide à la marche</strong> (canne, fauteuil roulant, déambulateur).</li></ul>"},{"i":"ea4c00370bbb","n":109,"o":"109-1","u":"Diagnostic positif","t":"Connaître les éléments de l’interrogatoire devant un trouble de la marche","q":"Quel est le principal facteur de risque iatrogénique de chute chez le sujet âgé à rechercher systématiquement lors de l'interrogatoire ?","a":"<p>Le principal facteur de risque de chute chez le sujet âgé est la <strong>liste complète des médicaments pris</strong>, notamment ceux prescrits dans le champ neuropsychiatrique qui peuvent induire une baisse de la tension artérielle et des troubles attentionnels.</p>"},{"i":"2b8a68f0c6ec","n":109,"o":"109-12","u":"Examens complémentaires","t":"Connaître l’indication et l’intérêt des examens d’imagerie devant un trouble de la marche ou de l’équilibre","q":"Comment l'imagerie est-elle utilisée dans l'évaluation d'un trouble de la marche ou de l'équilibre ?","a":"<p>L'imagerie n'est <strong>pas systématique</strong> et doit toujours être <strong>orientée par la clinique</strong>. Le choix de la technique (IRM médullaire vs IRM cérébrale) et de la zone à imager dépend de l'interrogatoire et de l'examen physique.</p>"},{"i":"b6e15bf1e158","n":109,"o":"109-12","u":"Examens complémentaires","t":"Connaître l’indication et l’intérêt des examens d’imagerie devant un trouble de la marche ou de l’équilibre","q":"Dans quel contexte clinique indique-t-on une IRM de la moelle spinale chez un patient présentant un trouble de la marche ou de l'équilibre ?","a":"Une IRM de la moelle spinale est indiquée en cas de suspicion clinique de :<ul><li><strong>Compression médullaire</strong></li><li><strong>Myélopathie</strong></li><li><strong>Atteinte cordonale postérieure</strong></li></ul>"},{"i":"e3ae68b65c80","n":109,"o":"109-12","u":"Examens complémentaires","t":"Connaître l’indication et l’intérêt des examens d’imagerie devant un trouble de la marche ou de l’équilibre","q":"Quelles sont les indications cliniques pour la réalisation d'une IRM cérébrale face à un trouble de la marche ou de l'équilibre ?","a":"Une IRM cérébrale est pertinente devant la suspicion clinique de :<ul><li><strong>Sclérose en plaques (SEP)</strong></li><li><strong>Hydrocéphalie chronique de l'adulte</strong> (HCS ou NPH)</li><li><strong>Lésion frontale</strong></li><li><strong>Accident vasculaire cérébral (AVC)</strong> ou <strong>état lacunaire</strong></li><li><strong>Tumeur cérébrale</strong></li></ul>"},{"i":"1d7f32f4fce8","n":109,"o":"109-13","u":"Examens complémentaires","t":"Citer les principaux examens complémentaires hors imagerie devant un trouble de la marche ou de l’équilibre","q":"Quel est l'intérêt d'une analyse quantifiée de la marche dans l'exploration d'un trouble de la marche ou de l'équilibre ?","a":"<p>L'analyse quantifiée de la marche, réalisable dans certains centres spécialisés, permet de mesurer des paramètres objectifs tels que la <strong>longueur et la durée des cycles</strong> de pas, ainsi que l'<strong>asymétrie du pas</strong>.</p>"},{"i":"5fdb8c69b184","n":109,"o":"109-13","u":"Examens complémentaires","t":"Citer les principaux examens complémentaires hors imagerie devant un trouble de la marche ou de l’équilibre","q":"Quand doit-on envisager un test à la lévodopa devant un trouble de la marche ou de l'équilibre ?","a":"<p>Le test à la lévodopa est un <strong>test thérapeutique</strong> à considérer devant une <strong>marche à petits pas</strong> ou une <strong>dystonie</strong>, dans le but de rechercher une éventuelle <strong>dopa-sensibilité</strong>.</p>"},{"i":"9ae606f0b4ae","n":109,"o":"109-13","u":"Examens complémentaires","t":"Citer les principaux examens complémentaires hors imagerie devant un trouble de la marche ou de l’équilibre","q":"Dans quel contexte clinique un électromyogramme (EMG) est-il indiqué devant un trouble de la marche ou de l'équilibre, et quels éléments peut-il révéler ?","a":"<p>L'EMG est indiqué en cas de suspicion de <ul><li><strong>neuropathies</strong>,</li><li><strong>myopathies</strong>,</li><li> ou <strong>sclérose latérale amyotrophique (SLA)</strong>.</li></ul> Il est également pertinent pour diagnostiquer un <strong>tremblement orthostatique</strong>, avec un EMG des membres inférieurs réalisé en position debout immobile.</p>"},{"i":"b920db4156f5","n":109,"o":"109-13","u":"Examens complémentaires","t":"Citer les principaux examens complémentaires hors imagerie devant un trouble de la marche ou de l’équilibre","q":"Quand faut-il réaliser un examen audiovestibulaire face à un trouble de la marche ou de l'équilibre ?","a":"<p>Un examen audiovestibulaire est nécessaire en cas de suspicion d'<strong>ataxie vestibulaire</strong>.</p>"},{"i":"c1d1bc3eb8d5","n":109,"o":"109-13","u":"Examens complémentaires","t":"Citer les principaux examens complémentaires hors imagerie devant un trouble de la marche ou de l’équilibre","q":"Dans quelle situation clinique le test de soustraction du liquide cérébro-spinal (LCS) est-il pertinent pour un trouble de la marche ou de l'équilibre ?","a":"<p>Le test de soustraction du LCS est un <strong>test thérapeutique</strong> indiqué en cas de suspicion d'<strong>hydrocéphalie à pression normale</strong>.</p>"},{"i":"6e6aaea135a0","n":109,"o":"109-2","u":"Diagnostic positif","t":"Connaître les modalités de l’examen d’un patient présentant un trouble de la marche","q":"Quelles sont les anomalies de la cinématique de la hanche, du tronc et des membres supérieurs à rechercher lors de l'examen d'un trouble de la marche ?","a":"<ul><li><strong>Hanche</strong> : Une <strong>circumduction</strong> du membre inférieur et un défaut d'extension en fin d'appui.</li><li><strong>Tronc</strong> : Un manque de dissociation des ceintures (typique de la maladie de <strong>Parkinson</strong>), une <strong>salutation</strong>, ou une <strong>inclinaison latérale</strong> due à une faiblesse du moyen fessier.</li><li><strong>Membres supérieurs</strong> : Une perte du <strong>ballant des bras</strong>, uni ou bilatérale.</li></ul>"},{"i":"76a197a03d7e","n":109,"o":"109-2","u":"Diagnostic positif","t":"Connaître les modalités de l’examen d’un patient présentant un trouble de la marche","q":"Quelle est la signification d'une instabilité au test de Romberg lors de l'examen d'un trouble de la marche ?","a":"<p>Une instabilité au test de Romberg signe une <strong>ataxie cérébelleuse</strong>, <strong>vestibulaire</strong> ou <strong>proprioceptive</strong>. Une aggravation de cette instabilité à la fermeture des yeux indique une origine <strong>sensorielle</strong> (proprioceptive ou vestibulaire), où la contribution visuelle est majeure.</p>"},{"i":"b342519f0101","n":109,"o":"109-2","u":"Diagnostic positif","t":"Connaître les modalités de l’examen d’un patient présentant un trouble de la marche","q":"Comment évalue-t-on l'équilibre statique lors de l'examen d'un trouble de la marche ?","a":"<p>L'équilibre statique est évalué par l'épreuve de <strong>Romberg</strong>. Le patient est debout, talons joints, pieds légèrement écartés, bras ballants ou tendus. On observe sa stabilité les <strong>yeux ouverts</strong>, puis les <strong>yeux fermés</strong>. Un sujet normal tient plus de 6 secondes les yeux fermés.</p>"},{"i":"b72941f3d5b6","n":109,"o":"109-2","u":"Diagnostic positif","t":"Connaître les modalités de l’examen d’un patient présentant un trouble de la marche","q":"Quelles anomalies de la cinématique articulaire de la cheville et du genou recherche-t-on lors de l'examen d'un trouble de la marche ?","a":"<ul><li><strong>Cheville / pied</strong> : Un contact initial par l'avant du pied (en <strong>équin</strong>) peut indiquer une spasticité du triceps sural ou un déficit des releveurs.</li><li><strong>Genou</strong> : On recherche un <strong>recurvatum</strong> en phase d'appui, ainsi qu'un <strong>défaut de flexion</strong> en phase oscillante, pouvant entraîner un fauchage.</li></ul>"},{"i":"c342f388a8c9","n":109,"o":"109-2","u":"Diagnostic positif","t":"Connaître les modalités de l’examen d’un patient présentant un trouble de la marche","q":"Comment évalue-t-on les réflexes posturaux lors de l'examen d'un trouble de la marche et que révèle leur altération ?","a":"<p>Les réflexes posturaux sont testés par l'examinateur qui, placé derrière le patient, exerce une <strong>rétropulsion brusque</strong>. Cette manœuvre évalue les réflexes d'anticipation. Leur altération peut être le signe d'une lésion des <strong>noyaux gris centraux</strong> ou des <strong>régions frontales</strong>.</p>"},{"i":"f198f1f4aa7c","n":109,"o":"109-2","u":"Diagnostic positif","t":"Connaître les modalités de l’examen d’un patient présentant un trouble de la marche","q":"Quelles sont les anomalies posturales spécifiques à rechercher dans les plans sagittal et frontal lors de l'examen d'un trouble de la marche ?","a":"<ul><li>Dans le <strong>plan sagittal</strong> : on recherche une <strong>camptocormie</strong> (flexion du tronc), une <strong>antécolis</strong> ou <strong>rétrocolis</strong> (atteinte de la nuque).</li><li>Dans le <strong>plan frontal</strong> : on recherche une <strong>inclinaison latérale marquée du tronc</strong>, connue sous le nom de <strong>Pisa syndrome</strong>. L'origine dystonique ou déficitaire doit être évaluée.</li></ul>"},{"i":"1b5ef34ea931","n":109,"o":"109-5","u":"Diagnostic positif","t":"Connaître les modalités du uiagnostic d’une boiterie (examen clinique, démarche diagnostique)","q":"Quelle est la caractéristique principale d'une boiterie avec salutation lors de l'examen clinique ?","a":"<p>La boiterie avec salutation se manifeste par une <strong>flexion antérieure du tronc en phase d'appui</strong>. Elle oriente vers un <strong>défaut d'extension de la hanche</strong> ou une <strong>perte de force du quadriceps</strong>.</p>"},{"i":"43e57223f321","n":109,"o":"109-5","u":"Diagnostic positif","t":"Connaître les modalités du uiagnostic d’une boiterie (examen clinique, démarche diagnostique)","q":"Comment l'examen clinique de la marche identifie-t-il une boiterie d'équilibration, également appelée boiterie de Trendelenburg ?","a":"<p>La boiterie de Trendelenburg est révélatrice d'une <strong>faiblesse du muscle moyen fessier</strong>. Elle se manifeste par un <strong>abaissement du bassin du côté non portant</strong> (du côté sain) et une <strong>inclinaison compensatrice du tronc</strong> vers le côté atteint pour maintenir l'équilibre.</p>"},{"i":"67ff2455f134","n":109,"o":"109-5","u":"Diagnostic positif","t":"Connaître les modalités du uiagnostic d’une boiterie (examen clinique, démarche diagnostique)","q":"Comment l'examen clinique de la marche identifie-t-il une boiterie d'esquive ?","a":"<p>La boiterie d'esquive est caractérisée par un <strong>raccourcissement du temps d'appui</strong> sur le membre inférieur douloureux, traduisant une tentative d'éviter la douleur.</p>"},{"i":"9cbdc1bdca0d","n":109,"o":"109-5","u":"Diagnostic positif","t":"Connaître les modalités du uiagnostic d’une boiterie (examen clinique, démarche diagnostique)","q":"Quelles sont les caractéristiques des boiteries déficitaires ?","a":"<p>Les boiteries déficitaires sont causées par un <strong>déficit moteur</strong>. Elles peuvent se manifester par un <strong>steppage</strong> (élévation excessive du genou pour éviter que la pointe du pied ne traîne) ou un <strong>fauchage</strong> (mouvement circulaire de la jambe), orientant vers une atteinte <strong>tronculaire, radiculaire ou pyramidale</strong>.</p>"},{"i":"11437d8ddc0e","n":109,"o":"109-6","u":"Définition","t":"Connaître la définition de l’astasie-abasie","q":"Comment définit-on spécifiquement l'astasie, l'une des composantes de l'astasie-abasie ?","a":"L'astasie est définie par une <strong>instabilité à la station debout</strong>, souvent associée à une tendance spontanée à la <strong>rétropulsion</strong>."},{"i":"1f238851bcd8","n":109,"o":"109-6","u":"Définition","t":"Connaître la définition de l’astasie-abasie","q":"Comment définit-on spécifiquement l'abasie, l'une des composantes de l'astasie-abasie, en précisant les pathologies à exclure ?","a":"L'abasie est définie par une <strong>incapacité à marcher</strong>, qui survient <strong>en l'absence de tout syndrome pyramidal ou parkinsonien</strong>."},{"i":"c60979eb7888","n":109,"o":"109-6","u":"Définition","t":"Connaître la définition de l’astasie-abasie","q":"Quelle est la définition générale de l'astasie-abasie dans le contexte des troubles de la marche ?","a":"L'astasie-abasie représente le degré maximal d'une <strong>apraxie de la marche</strong>, caractérisée par une incapacité du patient à tenir debout (astasie) ou à marcher (abasie)."},{"i":"10aee066ca40","n":109,"o":"109-9","u":"Etiologies","t":"Connaître le syndrome post chute","q":"Quelle est la définition du syndrome post-chute (ou phobie de la chute) ?","a":"<p>C'est une <strong>sidération des automatismes de l'équilibre et de la marche</strong>. Elle n'est pas expliquée par des lésions traumatiques ou neurologiques et n'est pas corrélée au caractère traumatisant ou à la fréquence de la chute, mais elle est d'autant plus marquée que le sujet est resté longtemps au sol.</p>"},{"i":"8b952d69abae","n":109,"o":"109-9","u":"Etiologies","t":"Connaître le syndrome post chute","q":"Quelle est la prise en charge du syndrome post-chute ?","a":"<p>Il s'agit d'une <strong>urgence gériatrique</strong> nécessitant une <strong>hospitalisation</strong>. La prise en charge repose sur la <strong>rééducation fonctionnelle</strong> et un <strong>soutien psychologique</strong>. Les psychotropes ont peu d'effet. Le pronostic fonctionnel est bon si la prise en charge est précoce, mais il évolue vers une perte d'autonomie complète sans intervention rapide.</p>"},{"i":"f55ce94f25ed","n":109,"o":"109-9","u":"Etiologies","t":"Connaître le syndrome post chute","q":"Quelles sont les manifestations cliniques du syndrome post-chute ?","a":"<ul><li>Une <strong>rétropulsion</strong> rendant la station debout impossible sans aide humaine (tendance rétropulsive lors du lever, avec appui talonnier et orteils en griffe dans les formes invétérées).</li><li>Une <strong>phobie de la marche</strong>, voire de la verticalisation (<strong>stasobasophobie</strong>) avec composante anxieuse majeure, agrippement à l'examinateur ou au mobilier.</li><li>Une marche avec aide humaine caractérisée par des <strong>petits pas glissés en appui talonnier</strong>, un retard d'initiation ou <strong>freezing</strong>.</li><li>Une <strong>hypertonie oppositionnelle</strong>.</li><li>Une altération des réactions d'adaptation posturale et des réactions parachutes.</li></ul>"}]};